import standards from '@nextnode-solutions/standards/oxlint'
import { defineConfig } from 'oxlint'

export default defineConfig({
	extends: [standards],
	// Setting ignorePatterns replaces oxlint's built-in ignore list, so
	// node_modules/dist are listed explicitly next to Syneva's build output,
	// generated sources and runtime artifacts (desk locks, pi shims, scratch).
	ignorePatterns: [
		'node_modules/**',
		'dist/**',
		// GENERATED by scripts/fetch-icons.mjs; re-run the script, don't lint it.
		'src/ui/icon-data.ts',
		'.desk/**',
		'.pi/**',
		'.prd/**',
		'prototypes/**',
		'.playwright-mcp/**',
	],
	overrides: [
		{
			// The token pool's pinned-library seam: @pierre/diffs pins a nominal-class
			// WorkerPoolManager (private fields, no structural half) and types helpers against the
			// full shiki v3 barrel (DiffsHighlighter) while syneva builds a lean shiki v4(core)
			// instance; DOM libs also lack DedicatedWorkerGlobalScope so the worker scope needs a
			// narrow view. Every assertion lives next to its seam and is documented there.
			// Token-pool files also log failures (an unhighlighted desk must show WHY, not stay
			// silent), and post worker messages without target-origin (workers post by identity,
			// the rule targets window contexts).
			files: [
				'src/ui/render/worker-pool.ts',
				'src/ui/worker/diff-token-worker.ts',
				'src/ui/render/token-pool/*.ts',
			],
			rules: {
				'nextnode/no-type-assertion': 'off',
				// The type-aware pass sees the same seams as unsafe (the nominal pool cast, the
				// DiffsHighlighter parameter shape, the window-scope view).
				'typescript/no-unsafe-type-assertion': 'off',
				'unicorn/require-post-message-target-origin': 'off',
				'eslint/no-console': 'off',
				// The pool's PoolJob/WindowTask records are one piece of shared mutable state the
				// class owns: settlement paths (window landed, worker crashed, options adopted)
				// mutate the same record through their parameters by design - copying it per call
				// would fork the state the countdown and the gate are read from.
				'eslint/no-param-reassign': 'off',
				// The single-class pool (pool.ts) is deliberate: the v1 book split the same state
				// machine across six modules whose only seams were call boundaries. Keep the file
				// cap from splitting it again.
				'eslint/max-lines': 'off',
			},
		},
		{
			// The hide-reviewed distill pass is a mechanical translation of @pierre's own
			// resolveRegion cursor walk (same counters, same collapsed-context handling, minus
			// dropped rows) - the pinned-library seam's shape, not a reviewable logic tree.
			// Splitting it would scatter one invariant (the lockstep ledger) across closures.
			files: ['src/ui/render/distill.ts'],
			rules: {
				'eslint/max-lines-per-function': 'off',
				'eslint/max-depth': 'off',
			},
		},
		{
			// The long-poll consumes the next queued event. Parallel requests would
			// reorder feedback and detach event ownership from its delivery.
			files: ['src/agent/desk-listener.ts'],
			rules: { 'eslint/no-await-in-loop': 'off' },
		},
		{
			// The question pipeline is sequential by design: the single desk correspondent
			// thread answers one event at a time, and answers post to the desk in question
			// order (the same class of exception as the desk-listener long-poll below).
			files: ['src/agent/pi-attachment.ts', 'src/agent/pi-delivery.ts'],
			rules: { 'eslint/no-await-in-loop': 'off' },
		},
		{
			// The integration test polls the desk state until the skipped-owner answer
			// appears: live polling, not parallelizable promise collection.
			files: ['src/agent/pi-attachment.integration.test.ts'],
			rules: { 'eslint/no-await-in-loop': 'off' },
		},
		{
			// The bench fixtures encode file counts and per-file sizes by design (an 8k-line
			// giant, a 2.4MB oversized file) and the browser bench reports with console.log
			// like perf-smoke does. The shared preset's readability rules (magic numbers,
			// function length, await depth) fight the fixture specs' shape, not a reviewable
			// logic path - drop them for the bench scripts only.
			files: [
				'benchmarks/bench-fixtures.mjs',
				'benchmarks/browser-bench.mjs',
				'benchmarks/perf-smoke.mjs',
			],
			rules: {
				'eslint/no-magic-numbers': 'off',
				'eslint/no-console': 'off',
				'eslint/max-lines': 'off',
				'eslint/max-lines-per-function': 'off',
				'eslint/max-depth': 'off',
				'nextnode/no-nullish-ternary-return': 'off',
				// The bench instruments (a page-side __bench projector, fetch/Worker hooks,
				// measured-and-sequenced key presses) are inherently serialized and
				// underscore-named on purpose: the page API surface they reach into is
				// syneva's own store singleton. Sequenced awaits (cold-open pipeline,
				// latency probes, churn loops) measure sequences - parallelizing them would
				// change the thing being measured.
				'eslint/no-underscore-dangle': 'off',
				'eslint/no-await-in-loop': 'off',
			},
		},
		{
			// The pi extension entry point default-exports its register function by
			// design: pi's loader contract, the same class of exception as framework
			// pages in the shared preset.
			files: ['extensions/syneva.ts'],
			rules: {
				'import/no-default-export': 'off',
			},
		},
		{
			// `types/standards-oxfmt.d.ts` describes the shared preset's default
			// export; the default is the shape being typed, not an export-style
			// choice this repo makes.
			files: ['types/**/*.d.ts'],
			rules: {
				'import/no-default-export': 'off',
			},
		},
	],
})
